     4→using System;
     5→using DotNetty.Buffers;
     6→using Nethermind.Core;
     7→using Nethermind.Core.Collections;
     8→using Nethermind.Core.Extensions;
     9→using Nethermind.Core.Specs;
    10→using Nethermind.Serialization.Rlp;
    11→
    12→namespace Nethermind.Network.P2P.Subprotocols.Eth.V63.Messages
    13→{
    14→    public class ReceiptsMessageSerializer : IZeroInnerMessageSerializer<ReceiptsMessage>
    15→    {
    16→        private readonly ISpecProvider _specProvider;
    17→        private readonly IRlpStreamDecoder<TxReceipt> _decoder;
    18→        private readonly Func<RlpStream, TxReceipt[]> _decodeArrayFunc;
    19→
    20→        public ReceiptsMessageSerializer(ISpecProvider specProvider) : this(specProvider, Rlp.GetStreamDecoder<TxReceipt>()!) { }
    21→
    22→        protected ReceiptsMessageSerializer(ISpecProvider specProvider, IRlpStreamDecoder<TxReceipt> decoder)
    23→        {
    24→            _specProvider = specProvider ?? throw new ArgumentNullException(nameof(specProvider));
    25→            _decoder = decoder ?? throw new ArgumentNullException(nameof(decoder));
    26→            _decodeArrayFunc = ctx => ctx.DecodeArray(nestedContext => _decoder.Decode(nestedContext)) ?? [];
    27→        }
    28→
    29→        public void Serialize(IByteBuffer byteBuffer, ReceiptsMessage message)
    30→        {
    31→            int totalLength = GetLength(message, out int contentLength);
    32→
    33→            byteBuffer.EnsureWritable(totalLength);
    34→            NettyRlpStream stream = new(byteBuffer);
    35→            stream.StartSequence(contentLength);
    36→
    37→            // Track last‐seen block number & its RLP behavior
    38→            long lastBlockNumber = -1;
    39→            RlpBehaviors behaviors = RlpBehaviors.None;
    40→
    41→            foreach (TxReceipt?[]? txReceipts in message.TxReceipts)
    42→            {
    43→                if (txReceipts is null)
    44→                {
    45→                    stream.Encode(Rlp.OfEmptySequence);
    46→                    continue;
    47→                }
    48→
    49→                int innerLength = GetInnerLength(txReceipts);
    50→                stream.StartSequence(innerLength);
    51→                foreach (TxReceipt? txReceipt in txReceipts)
    52→                {
    53→                    if (txReceipt is null)
    54→                    {
    55→                        stream.Encode(Rlp.OfEmptySequence);
    56→                        continue;
    57→                    }
    58→
    59→                    // Only fetch a new spec when the block number changes
    60→                    if (txReceipt.BlockNumber != lastBlockNumber)
    61→                    {
    62→                        lastBlockNumber = txReceipt.BlockNumber;
    63→                        behaviors = _specProvider.GetReceiptSpec(lastBlockNumber).IsEip658Enabled
    64→                                    ? RlpBehaviors.Eip658Receipts
    65→                                    : RlpBehaviors.None;
    66→                    }
    67→
    68→                    _decoder.Encode(stream, txReceipt, behaviors);
    69→                }
    70→            }
    71→        }
    72→
    73→        public ReceiptsMessage Deserialize(IByteBuffer byteBuffer)
    74→        {
    75→            if (byteBuffer.ReadableBytes == 0)
    76→            {
    77→                return ReceiptsMessage.Empty;
    78→            }
    79→
    80→            if (byteBuffer.GetByte(byteBuffer.ReaderIndex) == Rlp.OfEmptySequence[0])
    81→            {
    82→                byteBuffer.ReadByte();
    83→                return ReceiptsMessage.Empty;
    84→            }
    85→
    86→            RlpStream rlpStream = new NettyRlpStream(byteBuffer);
    87→            return Deserialize(rlpStream);
    88→        }
    89→
    90→        public ReceiptsMessage Deserialize(RlpStream rlpStream)
    91→        {
    92→            ArrayPoolList<TxReceipt[]> data = rlpStream.DecodeArrayPoolList(_decodeArrayFunc, true);
    93→            ReceiptsMessage message = new(data);
    94→
    95→            return message;
    96→        }
    97→
    98→        public int GetLength(ReceiptsMessage message, out int contentLength)
    99→        {
   100→            contentLength = 0;
   101→
   102→            for (int i = 0; i < message.TxReceipts.Count; i++)
   103→            {
   104→                TxReceipt?[]? txReceipts = message.TxReceipts[i];
   105→                if (txReceipts is null)
   106→                {
   107→                    contentLength += Rlp.OfEmptySequence.Length;
   108→                }
   109→                else
   110→                {
   111→                    contentLength += Rlp.LengthOfSequence(GetInnerLength(txReceipts));
   112→                }
   113→            }
   114→
   115→            return Rlp.LengthOfSequence(contentLength);
   116→        }
   117→
   118→        private int GetInnerLength(TxReceipt?[]? txReceipts)
   119→        {
   120→            if (txReceipts == null || txReceipts.Length == 0)
   121→                return 0;
   122→
   123→            int contentLength = 0;
   124→
   125→            // Track the last‐seen block number and its spec
   126→            long lastBlockNumber = -1;
   127→            RlpBehaviors behaviors = RlpBehaviors.None;
   128→
   129→            for (int i = 0; i < txReceipts.Length; i++)
   130→            {
   131→                TxReceipt? receipt = txReceipts[i];
   132→
   133→                if (receipt is null)
   134→                {
   135→                    contentLength += Rlp.OfEmptySequence.Length;
   136→                    continue;
   137→                }
   138→
   139→                // Only fetch a new spec when block number changes
   140→                if (lastBlockNumber != receipt.BlockNumber)
   141→                {
   142→                    lastBlockNumber = receipt.BlockNumber;
   143→                    behaviors = _specProvider.GetSpec((ForkActivation)receipt.BlockNumber).IsEip658Enabled
   144→                                ? RlpBehaviors.Eip658Receipts
   145→                                : RlpBehaviors.None;
   146→                }
   147→
   148→                contentLength += _decoder.GetLength(receipt, behaviors);
   149→            }
   150→
   151→            return contentLength;
   152→        }
   153→    }
   154→}
